-- ============================================================
-- Plan de cuentas — Objeto del gasto (Plan_de_cuentas_objeto_del_gasto.xlsx)
-- Reemplaza a la tabla "catalogo" como origen de Partida / Ítem / Clasificador.
--   Nivel 1 = Clasificador · Nivel 2 = Partida · Nivel 3 = Ítem
--   Las partidas sin ítems de nivel 3 se usan como ítem ellas mismas.
-- Ejecutar en: Supabase > SQL Editor, ANTES de formulacion.sql.
-- Se puede volver a ejecutar: actualiza los datos sin duplicar.
-- ============================================================

create table if not exists public.plan_cuentas (
  codigo           bigint primary key,
  denominacion     text not null,
  nivel            smallint not null check (nivel between 1 and 3),
  codigo_superior  bigint references public.plan_cuentas (codigo),
  agrupacion       text,
  pagina_fuente    integer,
  observaciones    text
);
create index if not exists plan_cuentas_superior_idx on public.plan_cuentas (codigo_superior);

-- Los niveles se insertan en orden (1, 2, 3) por la referencia al código superior
insert into public.plan_cuentas (codigo, denominacion, nivel, codigo_superior, agrupacion, pagina_fuente, observaciones)
