       codigo_superior = excluded.codigo_superior, agrupacion = excluded.agrupacion,
       pagina_fuente = excluded.pagina_fuente, observaciones = excluded.observaciones;

-- Lectura pública (no tiene datos sensibles)
alter table public.plan_cuentas enable row level security;
drop policy if exists "lectura plan_cuentas" on public.plan_cuentas;
create policy "lectura plan_cuentas" on public.plan_cuentas for select to anon, authenticated using (true);

notify pgrst, 'reload schema';

